package com.yilu.yinling.financial.controller;
import com.yilu.yinling.ai.agent.FinancialAgentOrchestrator; import com.yilu.yinling.common.response.Result; import com.yilu.yinling.financial.dto.FinancialAgentRequest; import com.yilu.yinling.financial.vo.FinancialAgentResponse; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/financial/agent") @Tag(name="AI银龄金融智能体") public class FinancialAgentController { private final FinancialAgentOrchestrator orchestrator; public FinancialAgentController(FinancialAgentOrchestrator o){orchestrator=o;} @PostMapping("/chat") @Operation(summary="运行多Agent养老金融决策链") public Result<FinancialAgentResponse> chat(Authentication a,@Valid @RequestBody FinancialAgentRequest r){return Result.ok(orchestrator.orchestrate((Long)a.getDetails(),r.message()));} }
